import{_ as a,o as r,c as t,a3 as i}from"./chunks/framework.B5WAEDB7.js";const o="/assets/images/yB5SYwm.png",f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/application-layer.md","filePath":"core-concepts/application-layer.md"}'),s={name:"core-concepts/application-layer.md"};function n(l,e,c,p,d,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="application-layer" tabindex="-1">Application layer <a class="header-anchor" href="#application-layer" aria-label="Permalink to &quot;Application layer&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Application layer.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+o+'"><br><i><a href="http://lethain.com/introduction-to-architecting-systems-for-scale/#platform_layer">Source: Intro to architecting systems for scale</a></i></p><p>Separating out the web layer from the application layer (also known as platform layer) allows you to scale and configure both layers independently. Adding a new API results in adding application servers without necessarily adding additional web servers. The <strong>single responsibility principle</strong> advocates for small and autonomous services that work together. Small teams with small services can plan more aggressively for rapid growth.</p><p>Workers in the application layer also help enable <a href="/core-concepts/asynchronism.html">asynchronism</a>.</p><h3 id="microservices" tabindex="-1">Microservices <a class="header-anchor" href="#microservices" aria-label="Permalink to &quot;Microservices&quot;">​</a></h3><p>Related to this discussion are <a href="https://en.wikipedia.org/wiki/Microservices" target="_blank" rel="noreferrer">microservices</a>, which can be described as a suite of independently deployable, small, modular services. Each service runs a unique process and communicates through a well-defined, lightweight mechanism to serve a business goal. <sup><a href="https://smartbear.com/learn/api-design/what-are-microservices">1</a></sup></p><p>Pinterest, for example, could have the following microservices: user profile, follower, feed, search, photo upload, etc.</p><h3 id="service-discovery" tabindex="-1">Service Discovery <a class="header-anchor" href="#service-discovery" aria-label="Permalink to &quot;Service Discovery&quot;">​</a></h3><p>Systems such as <a href="https://www.consul.io/docs/index.html" target="_blank" rel="noreferrer">Consul</a>, <a href="https://coreos.com/etcd/docs/latest" target="_blank" rel="noreferrer">Etcd</a>, and <a href="http://www.slideshare.net/sauravhaloi/introduction-to-apache-zookeeper" target="_blank" rel="noreferrer">Zookeeper</a> can help services find each other by keeping track of registered names, addresses, and ports. <a href="https://www.consul.io/intro/getting-started/checks.html" target="_blank" rel="noreferrer">Health checks</a> help verify service integrity and are often done using an <a href="#hypertext-transfer-protocol-http">HTTP</a> endpoint. Both Consul and Etcd have a built in <a href="#key-value-store">key-value store</a> that can be useful for storing config values and other shared data.</p><h3 id="disadvantage-s-application-layer" tabindex="-1">Disadvantage(s): application layer <a class="header-anchor" href="#disadvantage-s-application-layer" aria-label="Permalink to &quot;Disadvantage(s): application layer&quot;">​</a></h3><ul><li>Adding an application layer with loosely coupled services requires a different approach from an architectural, operations, and process viewpoint (vs a monolithic system).</li><li>Microservices can add complexity in terms of deployments and operations.</li></ul><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="http://lethain.com/introduction-to-architecting-systems-for-scale" target="_blank" rel="noreferrer">Intro to architecting systems for scale</a></li><li><a href="http://www.puncsky.com/blog/2016-02-13-crack-the-system-design-interview" target="_blank" rel="noreferrer">Crack the system design interview</a></li><li><a href="https://en.wikipedia.org/wiki/Service-oriented_architecture" target="_blank" rel="noreferrer">Service oriented architecture</a></li><li><a href="http://www.slideshare.net/sauravhaloi/introduction-to-apache-zookeeper" target="_blank" rel="noreferrer">Introduction to Zookeeper</a></li><li><a href="https://cloudncode.wordpress.com/2016/07/22/msa-getting-started/" target="_blank" rel="noreferrer">Here&#39;s what you need to know about building microservices</a></li></ul>',14)])])}const m=a(s,[["render",n]]);export{f as __pageData,m as default};
